    text = "\n\n".join(body).replace("\n\n- ", "\n- ").replace("\n\n|", "\n|")
    text = re.sub(r"\n{3,}", "\n\n", text)
    (OUT / f"task-{n}.md").write_text(f"# Lab 19, Task {n}: answer key\n\n{HEAD}\n\n" + text + "\n")
